const results = [];

for (const item of $input.all()) {
    let comments = [];
    let attachments = [];

    for (const key in item.json) {
        if (key.startsWith('Comment') && item.json[key]) {
            comments.push(item.json[key]);
        }
        if (key.startsWith('Attachment') && item.json[key]) {
            attachments.push(item.json[key]);
        }
    }

    results.push({
        json: {
            Summary: item.json.Summary || '',
            IssueId: item.json['Issue id'] || '',
            IssueType: item.json['Issue Type'] || '',
            Status: item.json.Status || '',
            Description: item.json.Description || '',
            Resolution: item.json.Resolution || '',
            Comments: comments,
            Attachments: attachments
        }
    });
}

return results;

const mainItem = $items("Has Attachments?")[0].json;

const attachmentItems = $input.all().flatMap(item => {
    const value = item.json?.data;

    if (Array.isArray(value)) {
        return value;
    }

    return [item.json];
});

const attachments = attachmentItems
    .map((a, index) => {
        const type = a.type || 'Unknown';
        const source = a.source || '';

        let extractor = 'unknown';

        if (/ocr/i.test(type)) {
            extractor = 'glm-ocr';
        } else if (/pdf/i.test(type)) {
            extractor = 'pdf-parser';
        } else if (/text|code/i.test(type)) {
            extractor = 'native-text';
        } else if (/spreadsheet|excel|xls/i.test(type)) {
            extractor = 'spreadsheet-parser';
        }

        const content = a.content || '';

        return {
            attachment_id: index + 1,

            source,

            type,

            mime_type: a.mime_type || '',

            extractor,

            content,

        };
    })
    .filter(a => a.content.trim() !== '');

mainItem.Unified_Attachment_Context = attachments;


return [{
    json: mainItem
}];

const input = $input.all();
if (input.length !== 1) throw new Error(`Expected exactly one Jira issue, received ${input.length}.`);
const row = input[0].json;
const issue_id = row.Issue_id;
const summary = row.Summary;
const description = row.Description;
const comments = row.Comments;
const attachments = row.Attachments;

const mainParts = [
    summary ? `Summary: ${summary}` : '',
    description ? `Description:\n${description}` : ''
].filter(Boolean);

const evidenceParts = [];
for (const a of attachments) {
    const meta = [a.name ? `Attachment Name: ${a.name}` : '', a.type ? `Attachment Type: ${a.type}` : '', a.mime_type ? `MIME Type: ${a.mime_type}` : '', a.extractor ? `Extraction Method: ${a.extractor}` : ''].filter(Boolean).join('\n');
    evidenceParts.push(`${meta}${meta ? '\n' : ''}Attachment Content:\n${a.content}`);
}
for (const c of comments.slice(-5)) evidenceParts.push(`Comment ${c.index}:\n${c.text}`);

const semantic_query = mainParts.join('\n\n').slice(0, 5500);
let evidence_query = evidenceParts.join('\n\n---\n\n').slice(0, 6500);
if (!evidence_query) evidence_query = semantic_query;
const bm25_query = [semantic_query, evidence_query !== semantic_query ? `Technical Evidence:\n${evidence_query}` : ''].filter(Boolean).join('\n\n').slice(0, 11000);

return [{
    json: {
        issue_id,
        summary,
        description,
        comments,
        attachments,
        semantic_query,
        evidence_query,
        bm25_query,
        schema_version: 2
    }
}];

