const response = $input.first().json;
const points = Array.isArray(response.result) ? response.result : [];
const groups = new Map();
for (const point of points) {
    const p = point.payload || {};
    const issueId = String(p.issue_id ?? p.issueId ?? point.id);
    if (!groups.has(issueId)) groups.set(issueId, {
        issue_id: issueId,
        chunks: []
    });
    groups.get(issueId).chunks.push({
        point_id: point.id,
        score: Number(point.score || 0),
        chunk_type: p.chunk_type || 'unknown',
        attachment_name: p.attachment_name || '',
        attachment_type: p.attachment_type || '',
        attachment_extractor: p.attachment_extractor || '',
        comment_index: p.comment_index ?? null,
        text: String(p.text || '')
    });
}
const candidates = [...groups.values()].map(c => {
    c.chunks.sort((a, b) => b.score - a.score);
    c.chunks = c.chunks.slice(0, 3);
    const w = [1, 0.35, 0.15];
    c.combined_score = c.chunks.reduce((s, ch, i) => s + ch.score * (w[i] || 0.1), 0);
    return c;
}).sort((a, b) => b.combined_score - a.combined_score).slice(0, 8);
const current = $('Prepare Query').first().json;
const rerank_candidates = candidates.map((c, i) => ({
    candidate_id: i + 1,
    issue_id: c.issue_id,
    retrieval_score: c.combined_score,
    chunks: c.chunks.slice(0, 2)
}));
const rerank_prompt = [
    'CURRENT JIRA ISSUE',
    `Summary: ${current.summary || ''}`,
    current.description ? `Description:\n${current.description.slice(0,3500)}` : '',
    current.evidence_query ? `Technical Evidence:\n${current.evidence_query.slice(0,4500)}` : '',
    '',
    'HISTORICAL CANDIDATES',
    JSON.stringify(rerank_candidates, null, 2),
    '',
    'Rank candidates by usefulness for diagnosing the current issue.',
    'Prioritize exact error messages, exception types, class names, method names, stack traces, modules, symptoms, root causes and proven resolutions.',
    'Do not invent evidence.',
    'Return ONLY a JSON array of {"candidate_id": number, "relevance": number, "reason": "brief evidence-based reason"}.',
    'relevance must be an integer 0-100.'
].filter(Boolean).join('\n');
return [{
    json: {
        ...current,
        candidate_count: candidates.length,
        candidates,
        rerank_candidates,
        rerank_prompt
    }
}];

const d = $input.first().json;
const selected = (d.ranked_candidates || []).filter(c => c.rank <= 5 || c.relevance >= 30).slice(0, 5);
const blocks = selected.map(c => {
    const chunks = (c.chunks || []).slice(0, 2).map((ch, i) => [
        `Evidence ${i+1}`,
        ch.chunk_type ? `Chunk Type: ${ch.chunk_type}` : '',
        ch.attachment_name ? `Attachment: ${ch.attachment_name}` : '',
        ch.comment_index != null ? `Comment: ${ch.comment_index}` : '',
        ch.text
    ].filter(Boolean).join('\n')).join('\n\n');
    return [`=== Historical Issue ${c.issue_id} ===`, `Relevance: ${c.relevance}/100`, c.reason ? `Why: ${c.reason}` : '', chunks].filter(Boolean).join('\n');
});
const current = [d.summary ? `Summary: ${d.summary}` : '', d.description ? `Description:\n${d.description}` : '', d.evidence_query ? `Technical Evidence:\n${d.evidence_query}` : '', d.comments?.length ? `Recent Comments:\n${d.comments.slice(-3).map(c=>`Comment ${c.index}: ${c.text}`).join('\n\n')}` : ''].filter(Boolean).join('\n\n');
const prompt = [
    'You are an experienced software debugging assistant.',
    'CURRENT JIRA ISSUE', current,
    'RETRIEVED HISTORICAL EVIDENCE', blocks.length ? blocks.join('\n\n') : 'No sufficiently relevant historical evidence was retrieved.',
    'Instructions:',
    'Use the historical evidence to diagnose the current issue.',
    'Prioritize exact technical evidence such as exception names, error messages, class/method names, modules and stack traces.',
    'Clearly distinguish evidence from inference. Never invent a root cause, fix, commit or configuration value.',
    'When evidence comes from a historical Jira issue, cite its issue ID.',
    'Explain likely root cause, strongest evidence, and recommended next debugging/fix steps.',
    'If evidence is insufficient or contradictory, state that explicitly.',
    'Return a practical answer suitable for a Jira ticket.'
].join('\n\n');
return [{
    json: {
        ...d,
        selected_candidates: selected.map(c => ({
            issue_id: c.issue_id,
            relevance: c.relevance,
            reason: c.reason
        })),
        final_context: blocks.join('\n\n'),
        llm_prompt: prompt
    }
}];

