const r = $input.first().json;
const b = $('Build Final LLM Context').first().json;
const answer = r.message?.content ?? r.response ?? r.content ?? '';
return [{
    json: {
        issue_id: b.issue_id,
        issue_type: b.issue_type,
        summary: b.summary,
        retrieval: {
            candidate_count: b.candidate_count || 0,
            selected_candidates: b.selected_candidates || []
        },
        answer: String(answer).trim(),
        evidence: b.final_context || '',
        ranked_candidates: b.ranked_candidates || []
    }
}];
